<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\Relations\HasOne;
class Transfer extends Model { use HasUuids; public $incrementing=false; protected $keyType='string'; protected $fillable=['transfer_reference','user_id','source_wallet_currency_account_id','beneficiary_id','beneficiary_account_id','quote_id','source_currency_code','destination_currency_code','source_amount_minor','recipient_amount_minor','provider_fee_minor','platform_fee_minor','exchange_rate','transfer_type','status','failure_reason','sandbox_provider_reference','hold_id','ledger_transaction_id','idempotency_key_id','sandbox_only','completed_at','cancelled_at','metadata']; protected $casts=['sandbox_only'=>'boolean','completed_at'=>'datetime','cancelled_at'=>'datetime','metadata'=>'array']; public function beneficiary(): BelongsTo { return $this->belongsTo(Beneficiary::class); } public function quote(): BelongsTo { return $this->belongsTo(TransferQuote::class,'quote_id'); } public function sourceAccount(): BelongsTo { return $this->belongsTo(WalletCurrencyAccount::class,'source_wallet_currency_account_id'); } public function events(): HasMany { return $this->hasMany(TransferEvent::class); } public function screenings(): HasMany { return $this->hasMany(TransferScreening::class); } public function attempts(): HasMany { return $this->hasMany(TransferAttempt::class); } public function receipt(): HasOne { return $this->hasOne(TransferReceipt::class); } public function hold(): BelongsTo { return $this->belongsTo(WalletHold::class,'hold_id'); } public function ledgerTransaction(): BelongsTo { return $this->belongsTo(LedgerTransaction::class,'ledger_transaction_id'); } }
